// Package db is the database runtime that code generated by the Alder
// compiler imports: one Table descriptor per `table` declaration, Select
// values built by Db.from/where/orderBy/limit/offset, the Store interface
// the effect steps call, and its SQLite implementation.
//
// Storage mapping (one SQL column per field, in declaration order):
//
//	Text, brands of Text   TEXT
//	Int                    INTEGER
//	Float                  REAL
//	Bool                   INTEGER 0 or 1
//	Date                   TEXT "YYYY-MM-DD"
//	Time                   TEXT, RFC 3339, fixed 9-digit fraction, UTC (EncodeTime)
//	payload-less union     TEXT, the constructor name
//	Maybe T                T's column, NULL for Nothing
//
// The SQL table name is the module-qualified Alder table name with "." →
// "__" ("Todo.Todo" → "Todo__Todo"). Every identifier in generated SQL is a
// double-quoted name taken from a descriptor; every value is a `?`
// placeholder argument, so no user data is ever spliced into SQL text.
package db

import (
	"fmt"
	"strconv"
	"strings"

	"alder/rt/eff"
)

// ColType is a column's storage type.
type ColType int

const (
	CText  ColType = iota // TEXT (Text and its brands)
	CInt                  // INTEGER
	CFloat                // REAL
	CBool                 // INTEGER 0/1
	CDate                 // TEXT YYYY-MM-DD
	CTime                 // TEXT RFC 3339, fixed 9-digit fraction, UTC
	CEnum                 // TEXT constructor name; orders by declaration
)

// Column describes one field of a table.
type Column struct {
	Name     string
	Type     ColType
	Nullable bool     // Maybe T
	Enum     []string // CEnum: constructor names in declaration order
	Unique   bool
	Ref      string   // table name for @ref (module-qualified, like Table.Name), "" otherwise
	OnDelete OnDelete // what deleting the referenced row does to this row (Ref only)
}

// OnDelete is a @ref column's delete rule: `@restrict` (the default), `@cascade` or `@setNull`.
type OnDelete int

const (
	Restrict OnDelete = iota // deleting a referenced row fails (no ON DELETE clause)
	Cascade                  // ON DELETE CASCADE: the referencing rows are deleted too
	SetNull                  // ON DELETE SET NULL: the reference becomes Nothing (a Maybe column)
)

// Table describes one `table`. Generated code builds one per table as a package var.
//
// Insert values: the record without id/created/updated; generated code
// passes the column values in Columns order with nil at those three
// positions.
type Table[T any] struct {
	Name    string   // "Todo" (module-qualified: "Todo.Todo" → SQL table "Todo__Todo")
	Columns []Column // in declaration order, including the id column
	ID      string   // the @id column
	Created string   // @created column or ""
	Updated string   // @updated column or ""
	Encode  func(T) []any
	Decode  func([]any) (T, error)
	ReadID  func(T) string
	SetID   func(T, string) T
	// Owner is the `@owner` column ("" for none) and User, for such a table, the signed-in user
	// of an app session value (the Env's Session), false when there is none: the scoped
	// operations (Mine, GetMineRow, …) act for that user. Neither is part of the stored schema.
	Owner string
	User  func(session any) (string, bool)
	// Key is the session field Owner is a partition by (`@partition org`: "org"; "" for
	// `@owner`, the user), and User then reads that field. Silo is the `silo` key whose store
	// holds the table ("" for the shared store): rt/db routes each step on it to the store of
	// the key's value (route). Neither is part of the stored schema.
	Key  string
	Silo string
}

// TableDesc is a Table without its Go type, for Ensure.
type TableDesc struct {
	Name    string
	Columns []Column
	ID      string
	Created string
	Updated string
}

// Desc is t without its Go type.
func (t *Table[T]) Desc() TableDesc {
	return TableDesc{Name: t.Name, Columns: t.Columns, ID: t.ID, Created: t.Created, Updated: t.Updated}
}

// SQLName is the SQL table name for an Alder table name: "." → "__".
func SQLName(table string) string { return strings.ReplaceAll(table, ".", "__") }

// quote makes a double-quoted SQL identifier.
func quote(name string) string { return `"` + strings.ReplaceAll(name, `"`, `""`) + `"` }

// literal makes a single-quoted SQL string literal (used only for enum
// constructor names, which come from descriptors).
func literal(s string) string { return `'` + strings.ReplaceAll(s, `'`, `''`) + `'` }

// Select is data; the store turns it into SQL. Build one with From and the
// functions below; they never modify their argument.
type Select[T any] struct {
	Table *Table[T]
	// Mine (Db.mine) adds the condition `Owner = <the signed-in user>` when the select runs (All,
	// First, CountRows: the user is the running effect's); SQL refuses to render it unresolved.
	Mine bool
	// Op names the scoped operation Mine came from for the trace and its failures ("" is
	// Db.mine; Db.scoped).
	Op     string
	Where  []Cond
	Order  []Order
	Limit  *int64
	Offset *int64
}

// CondKind is the kind of a Cond.
type CondKind int

const (
	Eq CondKind = iota
	Ne
	Lt
	Le
	Gt
	Ge
	Contains
	In
	IsNull
	IsNotNull
	And
	Or
	Not
	StartsWith
)

// Cond is one condition. Val is an encoded scalar (see encode.go), or []any
// for In; Subs holds the operands of And/Or/Not.
type Cond struct {
	Kind CondKind
	Col  string
	Val  any
	Subs []Cond
}

// Order is one ORDER BY term.
type Order struct {
	Col  string
	Desc bool
}

// From is Db.from: every row of t.
func From[T any](t *Table[T]) Select[T] { return Select[T]{Table: t} }

// Where is Db.where; several are combined with AND.
func Where[T any](c Cond, s Select[T]) Select[T] {
	s.Where = append(append([]Cond(nil), s.Where...), c)
	return s
}

// OrderBy is Db.orderBy; earlier calls take precedence.
func OrderBy[T any](o Order, s Select[T]) Select[T] {
	s.Order = append(append([]Order(nil), s.Order...), o)
	return s
}

// Limit is Db.limit.
func Limit[T any](n int64, s Select[T]) Select[T] { s.Limit = &n; return s }

// Offset is Db.offset.
func Offset[T any](n int64, s Select[T]) Select[T] { s.Offset = &n; return s }

func CEq(col string, v any) Cond         { return Cond{Kind: Eq, Col: col, Val: v} }
func CNe(col string, v any) Cond         { return Cond{Kind: Ne, Col: col, Val: v} }
func CLt(col string, v any) Cond         { return Cond{Kind: Lt, Col: col, Val: v} }
func CLe(col string, v any) Cond         { return Cond{Kind: Le, Col: col, Val: v} }
func CGt(col string, v any) Cond         { return Cond{Kind: Gt, Col: col, Val: v} }
func CGe(col string, v any) Cond         { return Cond{Kind: Ge, Col: col, Val: v} }
func CContains(col string, v any) Cond   { return Cond{Kind: Contains, Col: col, Val: v} }
func CStartsWith(col string, v any) Cond { return Cond{Kind: StartsWith, Col: col, Val: v} }
func CIn(col string, vs []any) Cond      { return Cond{Kind: In, Col: col, Val: vs} }
func CIsNull(col string) Cond            { return Cond{Kind: IsNull, Col: col} }
func CIsNotNull(col string) Cond         { return Cond{Kind: IsNotNull, Col: col} }

// CAnd holds when every condition of cs holds: CAnd of none is true.
func CAnd(cs []Cond) Cond { return Cond{Kind: And, Subs: cs} }

// COr holds when some condition of cs holds: COr of none is false.
func COr(cs []Cond) Cond { return Cond{Kind: Or, Subs: cs} }

func CNot(c Cond) Cond { return Cond{Kind: Not, Subs: []Cond{c}} }

func Asc(col string) Order  { return Order{Col: col} }
func Desc(col string) Order { return Order{Col: col, Desc: true} }

// SQL is a Select rendered for a store: Where is a boolean expression ("" for
// none) with `?` placeholders for Args; Order is the ORDER BY list without
// the keyword ("" for none); Limit/Offset are nil when not set.
type SQL struct {
	Where         string
	Args          []any
	Order         string
	Limit, Offset *int64
	// Err is set when the query must not run: a `.contains` or `.startsWith` text over
	// MaxPattern bytes (see patternErr). All and CountRows return it.
	Err error
}

// SQL renders s. Column names are quoted; Eq/Ne with a nil value become IS
// NULL / IS NOT NULL, and Ne is null-safe (IS NOT ?), so Nothing ≠ Just x; on a
// nullable column every condition is two-valued (see renderCond), so Db.not of
// one matches exactly the rows it does not;
// Contains is `lower(col) LIKE lower(?) ESCAPE '\'` with % _ \ in the value
// escaped (so they match literally), and StartsWith the same with the pattern
// anchored at the start; In with no values is `0=1`; And/Or of nothing is `1=1`/`0=1`;
// every And, Or and Not is parenthesized. Several Where conditions render as
// one And. Ordering by an enum column orders by declaration (a CASE over its
// constructors), and so do <, <=, >, >= on one.
func (s Select[T]) SQL() SQL {
	var out SQL
	if s.Mine {
		out.Err = fmt.Errorf("db: %w: a Db.mine select rendered without its owner (run it with All, First or CountRows)", eff.ErrInternal)
	}
	var cols []Column
	if s.Table != nil {
		cols = s.Table.Columns
	}
	for _, c := range s.Where {
		if out.Err == nil {
			out.Err = patternErr(c)
		}
	}
	switch len(s.Where) {
	case 0:
	case 1:
		out.Where = renderCond(s.Where[0], cols, &out.Args)
	default:
		out.Where = renderCond(CAnd(s.Where), cols, &out.Args)
	}
	terms := make([]string, len(s.Order))
	for i, o := range s.Order {
		expr := quote(o.Col)
		if c := enumCol(cols, o.Col); c != nil {
			expr = enumRank(expr, c.Enum)
		}
		if o.Desc {
			terms[i] = expr + " DESC"
		} else {
			terms[i] = expr + " ASC"
		}
	}
	out.Order = strings.Join(terms, ", ")
	out.Limit, out.Offset = s.Limit, s.Offset
	return out
}

// enumCol is the CEnum column named name of cols, or nil.
func enumCol(cols []Column, name string) *Column {
	for i, c := range cols {
		if c.Name == name && c.Type == CEnum && len(c.Enum) > 0 {
			return &cols[i]
		}
	}
	return nil
}

// enumRank is the declaration index of enum column expr's value (a CASE over its constructors).
func enumRank(expr string, names []string) string {
	var b strings.Builder
	b.WriteString("CASE " + expr)
	for j, name := range names {
		b.WriteString(" WHEN " + literal(name) + " THEN " + strconv.Itoa(j))
	}
	b.WriteString(" END")
	return b.String()
}

// column is the column named name of cols, or nil.
func column(cols []Column, name string) *Column {
	for i, c := range cols {
		if c.Name == name {
			return &cols[i]
		}
	}
	return nil
}

// MaxPattern is the longest text, in bytes, a `.contains` or `.startsWith` condition takes.
// SQLite refuses a LIKE pattern over ~50 KB ("LIKE or GLOB pattern too complex"), and below
// that a match costs the column's length times the pattern's: an app cuts a search query
// (the blog's is 100 characters); this is the backstop, with a message that says what failed.
const MaxPattern = 10000

// patternErr is the ErrFail of the first `.contains` or `.startsWith` in c whose text is over
// MaxPattern bytes, or nil.
func patternErr(c Cond) error {
	switch c.Kind {
	case Contains, StartsWith:
		if s, ok := c.Val.(string); ok && len(s) > MaxPattern {
			return &eff.ErrFail{Msg: fmt.Sprintf("search text too long (over %d bytes)", MaxPattern)}
		}
	case And, Or, Not:
		for _, sub := range c.Subs {
			if err := patternErr(sub); err != nil {
				return err
			}
		}
	}
	return nil
}

// renderCond renders c; cols (nil when unknown) lets Lt/Le/Gt/Ge on an enum column compare
// declaration order, as ORDER BY does, rather than the constructor names' spelling, and makes
// every condition on a nullable (Maybe) column two-valued, so NOT, AND and OR never see SQL's
// NULL: Eq/Ne render as IS / IS NOT; In whose list holds nil (Nothing) adds `OR col IS NULL`
// (`col IS NULL` alone when it holds only nil); and every leaf SQL could make NULL (Lt, Le, Gt,
// Ge, Contains, StartsWith, In) is wrapped as COALESCE((leaf), 0). IS forms are never NULL.
func renderCond(c Cond, cols []Column, args *[]any) string {
	col := quote(c.Col)
	nullable := false
	if k := column(cols, c.Col); k != nil {
		nullable = k.Nullable
	}
	twoValued := func(leaf string) string {
		if nullable {
			return "COALESCE((" + leaf + "), 0)"
		}
		return leaf
	}
	bin := func(op string) string {
		if e := enumCol(cols, c.Col); e != nil && op != "=" && op != "IS" && op != "IS NOT" {
			if name, ok := c.Val.(string); ok {
				for j, n := range e.Enum {
					if n == name {
						*args = append(*args, int64(j))
						return twoValued(enumRank(col, e.Enum) + " " + op + " ?")
					}
				}
			}
		}
		*args = append(*args, c.Val)
		return twoValued(col + " " + op + " ?")
	}
	switch c.Kind {
	case Eq:
		if c.Val == nil {
			return col + " IS NULL"
		}
		if nullable {
			*args = append(*args, c.Val)
			return col + " IS ?"
		}
		return bin("=")
	case Ne:
		if c.Val == nil {
			return col + " IS NOT NULL"
		}
		*args = append(*args, c.Val)
		return col + " IS NOT ?"
	case Lt:
		return bin("<")
	case Le:
		return bin("<=")
	case Gt:
		return bin(">")
	case Ge:
		return bin(">=")
	case Contains, StartsWith:
		s, ok := c.Val.(string)
		if !ok {
			return "0=1" // only Text columns have .contains and .startsWith
		}
		pat := escapeLike(s) + "%"
		if c.Kind == Contains {
			pat = "%" + pat
		}
		*args = append(*args, pat)
		return twoValued("lower(" + col + `) LIKE lower(?) ESCAPE '\'`)
	case In:
		vs, _ := c.Val.([]any)
		var vals []any
		hasNil := false
		for _, v := range vs {
			if v == nil {
				hasNil = true
			} else {
				vals = append(vals, v)
			}
		}
		if len(vals) == 0 {
			if hasNil {
				return col + " IS NULL"
			}
			return "0=1"
		}
		*args = append(*args, vals...)
		in := col + " IN (" + strings.TrimSuffix(strings.Repeat("?, ", len(vals)), ", ") + ")"
		if hasNil {
			in = "(" + in + " OR " + col + " IS NULL)"
		}
		return twoValued(in)
	case IsNull:
		return col + " IS NULL"
	case IsNotNull:
		return col + " IS NOT NULL"
	case And, Or:
		if len(c.Subs) == 0 {
			if c.Kind == And {
				return "1=1"
			}
			return "0=1"
		}
		op := " AND "
		if c.Kind == Or {
			op = " OR "
		}
		parts := make([]string, len(c.Subs))
		for i, sub := range c.Subs {
			parts[i] = renderCond(sub, cols, args)
		}
		return "(" + strings.Join(parts, op) + ")"
	case Not:
		if len(c.Subs) != 1 {
			return "0=1"
		}
		return "NOT (" + renderCond(c.Subs[0], cols, args) + ")"
	}
	return "0=1" // unknown kind: match nothing
}

func escapeLike(s string) string {
	return strings.NewReplacer(`\`, `\\`, `%`, `\%`, `_`, `\_`).Replace(s)
}
